// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAdmins List admins (permission manage_admins)
	// (GET /admin/v1/admins)
	ListAdmins(ctx context.Context, request ListAdminsRequestObject) (ListAdminsResponseObject, error)
	// InviteAdmin Invite an admin (permission manage_admins). The invitation link is emailed, never returned.
	// (POST /admin/v1/admins)
	InviteAdmin(ctx context.Context, request InviteAdminRequestObject) (InviteAdminResponseObject, error)
	// ChangeAdminRole Change an admin's role (permission manage_admins; not self; keeps >= 1 super_admin)
	// (PUT /admin/v1/admins/{id}/role)
	ChangeAdminRole(ctx context.Context, request ChangeAdminRoleRequestObject) (ChangeAdminRoleResponseObject, error)
	// ListAuditEvents List audit events, newest first (permission view_audit)
	// (GET /admin/v1/audit-events)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// ListCustomers List customers (permission view_customers)
	// (GET /admin/v1/customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// LookupCustomers Find customers by phone number via the blind index (permission view_customers)
	// (POST /admin/v1/customers/lookup)
	LookupCustomers(ctx context.Context, request LookupCustomersRequestObject) (LookupCustomersResponseObject, error)
	// GetCustomer Get one customer (permission view_customers)
	// (GET /admin/v1/customers/{id})
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// DisableCustomer Disable a customer and revoke all sessions (permission manage_customers; idempotent)
	// (POST /admin/v1/customers/{id}/disable)
	DisableCustomer(ctx context.Context, request DisableCustomerRequestObject) (DisableCustomerResponseObject, error)
	// EnableCustomer Re-enable a customer (permission manage_customers; idempotent)
	// (POST /admin/v1/customers/{id}/enable)
	EnableCustomer(ctx context.Context, request EnableCustomerRequestObject) (EnableCustomerResponseObject, error)
	// GetCustomerPersonalInfoMasked Masked personal information (permission view_customers)
	// (GET /admin/v1/customers/{id}/personal-info)
	GetCustomerPersonalInfoMasked(ctx context.Context, request GetCustomerPersonalInfoMaskedRequestObject) (GetCustomerPersonalInfoMaskedResponseObject, error)
	// RevealCustomerPersonalInfo Reveal full personal information with a reason (permission reveal_customer_pii; audited)
	// (POST /admin/v1/customers/{id}/personal-info/reveal)
	RevealCustomerPersonalInfo(ctx context.Context, request RevealCustomerPersonalInfoRequestObject) (RevealCustomerPersonalInfoResponseObject, error)
	// RevokeCustomerSessions Revoke all sessions of a customer (permission manage_customers)
	// (DELETE /admin/v1/customers/{id}/sessions)
	RevokeCustomerSessions(ctx context.Context, request RevokeCustomerSessionsRequestObject) (RevokeCustomerSessionsResponseObject, error)
	// GetAdminMe Current admin session; the only admin endpoint reachable at AAL1
	// (GET /admin/v1/me)
	GetAdminMe(ctx context.Context, request GetAdminMeRequestObject) (GetAdminMeResponseObject, error)
	// ListServiceClients List machine clients managed by identity-service (permission manage_service_clients)
	// (GET /admin/v1/service-clients)
	ListServiceClients(ctx context.Context, request ListServiceClientsRequestObject) (ListServiceClientsResponseObject, error)
	// CreateServiceClient Register a client_credentials client (permission manage_service_clients; secret returned once)
	// (POST /admin/v1/service-clients)
	CreateServiceClient(ctx context.Context, request CreateServiceClientRequestObject) (CreateServiceClientResponseObject, error)
	// DeleteServiceClient Delete a machine client; its tokens stop working within 30 s (permission manage_service_clients)
	// (DELETE /admin/v1/service-clients/{client_id})
	DeleteServiceClient(ctx context.Context, request DeleteServiceClientRequestObject) (DeleteServiceClientResponseObject, error)
	// GetServiceClient Get one machine client (permission manage_service_clients)
	// (GET /admin/v1/service-clients/{client_id})
	GetServiceClient(ctx context.Context, request GetServiceClientRequestObject) (GetServiceClientResponseObject, error)
	// RotateServiceClientSecret Replace the client secret; the old one stops working immediately (permission manage_service_clients)
	// (POST /admin/v1/service-clients/{client_id}/rotate-secret)
	RotateServiceClientSecret(ctx context.Context, request RotateServiceClientSecretRequestObject) (RotateServiceClientSecretResponseObject, error)
	// ListMachineAuditEvents List audit events, newest first (scope audit:read)
	// (GET /m2m/v1/audit-events)
	ListMachineAuditEvents(ctx context.Context, request ListMachineAuditEventsRequestObject) (ListMachineAuditEventsResponseObject, error)
	// GetMachineCustomer Customer status for service clients (scope customers:read); no personal data
	// (GET /m2m/v1/customers/{id})
	GetMachineCustomer(ctx context.Context, request GetMachineCustomerRequestObject) (GetMachineCustomerResponseObject, error)
	// GetMe Current customer profile
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update the current customer's profile (requires verified email)
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// EraseMyPersonalInfo Erase the caller's personal information (crypto-shredding; any authenticated customer)
	// (DELETE /v1/me/personal-info)
	EraseMyPersonalInfo(ctx context.Context, request EraseMyPersonalInfoRequestObject) (EraseMyPersonalInfoResponseObject, error)
	// GetMyPersonalInfo Read the caller's decrypted personal information
	// (GET /v1/me/personal-info)
	GetMyPersonalInfo(ctx context.Context, request GetMyPersonalInfoRequestObject) (GetMyPersonalInfoResponseObject, error)
	// PutMyPersonalInfo Replace the caller's personal information (verified email required)
	// (PUT /v1/me/personal-info)
	PutMyPersonalInfo(ctx context.Context, request PutMyPersonalInfoRequestObject) (PutMyPersonalInfoResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

